const reportData = $input.first().json;

// ============================================================
// CONFIGURAÇÃO
// ============================================================
const THEME = 'dark'; // 'dark' ou 'light'
const LOGO_URL = 'https://example.com/assets/company-logo.png';
const COMPANY_NAME = 'Example Real Estate Company';
const QR_BASE_URL = 'https://example.com/verify/'; // URL base para verificação
// ============================================================

// Gerar ID único para verificação
const reportId = `VIS-${reportData.codigo_imovel}-${Date.now().toString(36).toUpperCase()}`;
const qrData = encodeURIComponent(`${QR_BASE_URL}${reportId}`);
const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${qrData}&bgcolor=${THEME === 'dark' ? '1e2023' : 'ffffff'}&color=${THEME === 'dark' ? 'f0f0f0' : '1a1a1e'}&format=png`;

// ============================================================
// TEMAS
// ============================================================
const themes = {
    dark: {
        bodyBg: '#141416',
        contentBg: '#1a1a1e',
        headerBg: 'linear-gradient(135deg, #0d0d0f 0%, #1e2023 50%, #252528 100%)',
        gold: '#c9a96e',
        goldLight: '#d4b878',
        goldDim: 'rgba(201, 169, 110, 0.12)',
        textPrimary: '#f0f0f0',
        textSecondary: '#a0a0a4',
        textMuted: '#6a6a6e',
        cardBg: '#1e2023',
        cardBorder: '#2a2a2e',
        cardElevated: '#252528',
        tableBg: '#1e2023',
        tableHeaderBg: '#252528',
        tableRowAlt: '#1a1a1e',
        tableBorder: '#2a2a2e',
        badgeDangerBg: 'rgba(220, 53, 69, 0.12)',
        badgeDangerColor: '#ff6b7a',
        badgeDangerBorder: 'rgba(220, 53, 69, 0.3)',
        badgeWarningBg: 'rgba(234, 88, 12, 0.12)',
        badgeWarningColor: '#fb923c',
        badgeWarningBorder: 'rgba(234, 88, 12, 0.3)',
        badgeSuccessBg: 'rgba(40, 167, 69, 0.12)',
        badgeSuccessColor: '#4ade80',
        badgeSuccessBorder: 'rgba(40, 167, 69, 0.3)',
        badgeInfoBg: 'rgba(23, 162, 184, 0.12)',
        badgeInfoColor: '#67e8f9',
        badgeInfoBorder: 'rgba(23, 162, 184, 0.3)',
        badgeNeutralBg: 'rgba(108, 117, 125, 0.12)',
        badgeNeutralColor: '#9ca3af',
        badgeNeutralBorder: 'rgba(108, 117, 125, 0.3)',
        summaryBg: 'linear-gradient(135deg, #252528, #1e2023)',
        summaryBorder: '#2a2a2e',
        dividerColor: '#2a2a2e',
        footerBg: '#141416',
        noChangeBg: 'rgba(74, 222, 128, 0.08)',
        noChangeBorder: 'rgba(74, 222, 128, 0.2)',
        noChangeColor: '#4ade80',
        recBg: 'rgba(201, 169, 110, 0.08)',
        recBorder: 'rgba(201, 169, 110, 0.2)',
        entradaBg: '#1a1a1e',
        entradaBorder: '#2a2a2e',
        saidaBg: 'rgba(220, 53, 69, 0.06)',
        saidaBorder: 'rgba(220, 53, 69, 0.2)',
        chartBg: '#252528',
        statCardBg: '#252528',
    },
    light: {
        bodyBg: '#f8f8f9',
        contentBg: '#ffffff',
        headerBg: 'linear-gradient(135deg, #1a1a1e 0%, #2a2d31 50%, #3a3d41 100%)',
        gold: '#c9a96e',
        goldLight: '#d4b878',
        goldDim: 'rgba(201, 169, 110, 0.1)',
        textPrimary: '#1a1a1e',
        textSecondary: '#4a4a4e',
        textMuted: '#8a8a8e',
        cardBg: '#ffffff',
        cardBorder: '#e8e8ea',
        cardElevated: '#f5f5f7',
        tableBg: '#ffffff',
        tableHeaderBg: '#1e2023',
        tableRowAlt: '#f8f8f9',
        tableBorder: '#e8e8ea',
        badgeDangerBg: '#fef2f2',
        badgeDangerColor: '#dc2626',
        badgeDangerBorder: '#fecaca',
        badgeWarningBg: '#fff7ed',
        badgeWarningColor: '#ea580c',
        badgeWarningBorder: '#fed7aa',
        badgeSuccessBg: '#f0fdf4',
        badgeSuccessColor: '#16a34a',
        badgeSuccessBorder: '#bbf7d0',
        badgeInfoBg: '#f0faff',
        badgeInfoColor: '#0891b2',
        badgeInfoBorder: '#a5f3fc',
        badgeNeutralBg: '#f8f9fa',
        badgeNeutralColor: '#6c757d',
        badgeNeutralBorder: '#dee2e6',
        summaryBg: 'linear-gradient(135deg, #f8f8f9, #ffffff)',
        summaryBorder: '#e8e8ea',
        dividerColor: '#e8e8ea',
        footerBg: '#f8f8f9',
        noChangeBg: '#f0fdf4',
        noChangeBorder: '#bbf7d0',
        noChangeColor: '#16a34a',
        recBg: '#fffbeb',
        recBorder: '#fde68a',
        entradaBg: '#f8f8f9',
        entradaBorder: '#e8e8ea',
        saidaBg: '#fef2f2',
        saidaBorder: '#fecaca',
        chartBg: '#f8f8f9',
        statCardBg: '#f8f8f9',
    }
};

const t = themes[THEME];

// ============================================================
// FUNÇÕES AUXILIARES
// ============================================================
function getClassificationDetails(classification) {
    switch (classification) {
        case 'desgaste_natural':
            return { text: 'Desgaste Natural', badgeBg: t.badgeNeutralBg, badgeColor: t.badgeNeutralColor, badgeBorder: t.badgeNeutralBorder, icon: '⏳' };
        case 'dano_inquilino':
            return { text: 'Dano Inquilino', badgeBg: t.badgeDangerBg, badgeColor: t.badgeDangerColor, badgeBorder: t.badgeDangerBorder, icon: '⚠️' };
        case 'melhoria':
            return { text: 'Melhoria', badgeBg: t.badgeSuccessBg, badgeColor: t.badgeSuccessColor, badgeBorder: t.badgeSuccessBorder, icon: '✅' };
        case 'item_ausente':
            return { text: 'Item Ausente', badgeBg: t.badgeWarningBg, badgeColor: t.badgeWarningColor, badgeBorder: t.badgeWarningBorder, icon: '❌' };
        case 'item_adicionado':
            return { text: 'Item Adicionado', badgeBg: t.badgeInfoBg, badgeColor: t.badgeInfoColor, badgeBorder: t.badgeInfoBorder, icon: '➕' };
        case 'indefinido':
        default:
            return { text: 'Indefinido', badgeBg: t.badgeNeutralBg, badgeColor: t.badgeNeutralColor, badgeBorder: t.badgeNeutralBorder, icon: '❓' };
    }
}

function getGravidadeDetails(gravidade) {
    switch (gravidade) {
        case 'leve':
            return { text: 'Leve', badgeBg: t.badgeSuccessBg, badgeColor: t.badgeSuccessColor, badgeBorder: t.badgeSuccessBorder, icon: '🟢', chartColor: '#4ade80' };
        case 'moderada':
            return { text: 'Moderada', badgeBg: t.badgeWarningBg, badgeColor: t.badgeWarningColor, badgeBorder: t.badgeWarningBorder, icon: '🟡', chartColor: '#fb923c' };
        case 'grave':
            return { text: 'Grave', badgeBg: t.badgeDangerBg, badgeColor: t.badgeDangerColor, badgeBorder: t.badgeDangerBorder, icon: '🔴', chartColor: '#ff6b7a' };
        default:
            return { text: 'N/A', badgeBg: t.badgeNeutralBg, badgeColor: t.badgeNeutralColor, badgeBorder: t.badgeNeutralBorder, icon: '⚪', chartColor: '#9ca3af' };
    }
}

function getAmbienteIcon(ambiente) {
    const lower = (ambiente || '').toLowerCase();
    if (lower.includes('sala')) return '🛋️';
    if (lower.includes('cozinha')) return '🍳';
    if (lower.includes('quarto')) return '🛏️';
    if (lower.includes('banheiro') || lower.includes('wc')) return '🚿';
    if (lower.includes('varanda') || lower.includes('sacada')) return '🌿';
    if (lower.includes('garagem')) return '🚗';
    if (lower.includes('área') || lower.includes('lavanderia')) return '🧺';
    if (lower.includes('corredor') || lower.includes('hall')) return '🚪';
    return '📍';
}

// ============================================================
// PROCESSAMENTO DE DADOS
// ============================================================

// Contadores de gravidade
const gravidadeContadores = { leve: 0, moderada: 0, grave: 0 };
if (reportData.divergencias && reportData.divergencias.length > 0) {
    reportData.divergencias.forEach(div => {
        if (div.gravidade && gravidadeContadores.hasOwnProperty(div.gravidade)) {
            gravidadeContadores[div.gravidade]++;
        }
    });
}

const totalDivergencias = reportData.total_divergencias || (reportData.divergencias ? reportData.divergencias.length : 0);

// ============================================================
// PIE CHART SVG
// ============================================================
function generatePieChart() {
    const total = gravidadeContadores.leve + gravidadeContadores.moderada + gravidadeContadores.grave;
    if (total === 0) return '<p style="text-align:center; color:' + t.textMuted + ';">Sem dados para gráfico</p>';

    const circumference = 251.327; // 2 * π * 40
    const radius = 40;

    // Calcular porcentagens
    const percentGrave = (gravidadeContadores.grave / total) * 100;
    const percentModerada = (gravidadeContadores.moderada / total) * 100;
    const percentLeve = (gravidadeContadores.leve / total) * 100;

    // Calcular dash arrays
    const dashGrave = (percentGrave / 100) * circumference;
    const dashModerada = (percentModerada / 100) * circumference;
    const dashLeve = (percentLeve / 100) * circumference;

    // Calcular offsets (cada fatia começa onde a anterior terminou)
    const offsetGrave = 0;
    const offsetModerada = -dashGrave;
    const offsetLeve = -(dashGrave + dashModerada);

    const graveColor = THEME === 'dark' ? '#ff6b7a' : '#dc2626';
    const moderadaColor = THEME === 'dark' ? '#fb923c' : '#ea580c';
    const leveColor = THEME === 'dark' ? '#4ade80' : '#16a34a';
    const bgCircleColor = THEME === 'dark' ? '#2a2a2e' : '#e8e8ea';

    return `
        <div style="display:flex; align-items:center; gap:32px; padding:24px; background:${t.chartBg}; border-radius:14px; border:1px solid ${t.cardBorder}; margin-bottom:28px;">
            <div style="width:130px; height:130px; flex-shrink:0;">
                <svg viewBox="0 0 100 100" style="transform:rotate(-90deg); width:100%; height:100%;">
                    <circle cx="50" cy="50" r="${radius}" fill="none" stroke="${bgCircleColor}" stroke-width="18"/>
                    ${gravidadeContadores.grave > 0 ? `<circle cx="50" cy="50" r="${radius}" fill="none" stroke="${graveColor}" stroke-width="18" stroke-dasharray="${dashGrave} ${circumference}" stroke-dashoffset="${offsetGrave}" stroke-linecap="round"/>` : ''}
                    ${gravidadeContadores.moderada > 0 ? `<circle cx="50" cy="50" r="${radius}" fill="none" stroke="${moderadaColor}" stroke-width="18" stroke-dasharray="${dashModerada} ${circumference}" stroke-dashoffset="${offsetModerada}" stroke-linecap="round"/>` : ''}
                    ${gravidadeContadores.leve > 0 ? `<circle cx="50" cy="50" r="${radius}" fill="none" stroke="${leveColor}" stroke-width="18" stroke-dasharray="${dashLeve} ${circumference}" stroke-dashoffset="${offsetLeve}" stroke-linecap="round"/>` : ''}
                </svg>
            </div>
            <div style="flex:1;">
                <div style="font-size:13px; font-weight:700; color:${t.textPrimary}; margin-bottom:16px;">Distribuição por Gravidade</div>
                ${gravidadeContadores.grave > 0 ? `
                <div style="display:flex; align-items:center; gap:10px; margin-bottom:10px;">
                    <div style="width:14px; height:14px; border-radius:4px; background:${graveColor}; flex-shrink:0;"></div>
                    <span style="font-size:13px; color:${t.textSecondary};"><strong style="color:${t.textPrimary};">${gravidadeContadores.grave}</strong> Graves (${Math.round(percentGrave)}%)</span>
                </div>` : ''}
                ${gravidadeContadores.moderada > 0 ? `
                <div style="display:flex; align-items:center; gap:10px; margin-bottom:10px;">
                    <div style="width:14px; height:14px; border-radius:4px; background:${moderadaColor}; flex-shrink:0;"></div>
                    <span style="font-size:13px; color:${t.textSecondary};"><strong style="color:${t.textPrimary};">${gravidadeContadores.moderada}</strong> Moderadas (${Math.round(percentModerada)}%)</span>
                </div>` : ''}
                ${gravidadeContadores.leve > 0 ? `
                <div style="display:flex; align-items:center; gap:10px; margin-bottom:10px;">
                    <div style="width:14px; height:14px; border-radius:4px; background:${leveColor}; flex-shrink:0;"></div>
                    <span style="font-size:13px; color:${t.textSecondary};"><strong style="color:${t.textPrimary};">${gravidadeContadores.leve}</strong> Leves (${Math.round(percentLeve)}%)</span>
                </div>` : ''}
            </div>
        </div>
    `;
}

// ============================================================
// STATS CARDS
// ============================================================
function generateStatsCards() {
    let html = '<div style="display:grid; grid-template-columns:repeat(3, 1fr); gap:14px; margin-bottom:28px;">';

    // Total
    html += `
        <div style="padding:20px; background:${t.statCardBg}; border-radius:12px; border:1px solid ${t.cardBorder}; text-align:center;">
            <div style="font-size:32px; font-weight:800; color:${t.textPrimary}; line-height:1; margin-bottom:6px;">${totalDivergencias}</div>
            <div style="font-size:10px; font-weight:700; color:${t.textMuted}; text-transform:uppercase; letter-spacing:0.05em;">Total Divergências</div>
        </div>
    `;

    // Graves
    html += `
        <div style="padding:20px; background:${t.badgeDangerBg}; border-radius:12px; border:1px solid ${t.badgeDangerBorder}; text-align:center;">
            <div style="font-size:32px; font-weight:800; color:${t.badgeDangerColor}; line-height:1; margin-bottom:6px;">${gravidadeContadores.grave}</div>
            <div style="font-size:10px; font-weight:700; color:${t.badgeDangerColor}; text-transform:uppercase; letter-spacing:0.05em;">Graves</div>
        </div>
    `;

    // Moderadas
    html += `
        <div style="padding:20px; background:${t.badgeWarningBg}; border-radius:12px; border:1px solid ${t.badgeWarningBorder}; text-align:center;">
            <div style="font-size:32px; font-weight:800; color:${t.badgeWarningColor}; line-height:1; margin-bottom:6px;">${gravidadeContadores.moderada}</div>
            <div style="font-size:10px; font-weight:700; color:${t.badgeWarningColor}; text-transform:uppercase; letter-spacing:0.05em;">Moderadas</div>
        </div>
    `;

    html += '</div>';

    // Cards por tipo/classificação
    const tipos = reportData.divergencias_por_tipo || {};
    const tiposAtivos = Object.entries(tipos).filter(([_, count]) => count > 0);

    if (tiposAtivos.length > 0) {
        html += `<div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(140px, 1fr)); gap:12px; margin-bottom:28px;">`;
        tiposAtivos.forEach(([type, count]) => {
            const details = getClassificationDetails(type);
            html += `
                <div style="padding:14px 16px; background:${details.badgeBg}; border-radius:10px; border:1px solid ${details.badgeBorder}; display:flex; align-items:center; gap:12px;">
                    <span style="font-size:20px;">${details.icon}</span>
                    <div>
                        <div style="font-size:18px; font-weight:700; color:${details.badgeColor};">${count}</div>
                        <div style="font-size:10px; font-weight:600; color:${details.badgeColor}; text-transform:uppercase;">${details.text}</div>
                    </div>
                </div>
            `;
        });
        html += '</div>';
    }

    return html;
}

// ============================================================
// DIVERGÊNCIAS (CARDS AGRUPADOS POR AMBIENTE)
// ============================================================
function generateDivergencias() {
    if (!reportData.divergencias || reportData.divergencias.length === 0) {
        return `
            <div style="text-align:center; padding:40px 20px; background:${t.cardElevated}; border-radius:14px; border:1px solid ${t.cardBorder}; margin-bottom:28px;">
                <div style="font-size:28px; margin-bottom:12px;">✅</div>
                <div style="font-size:14px; font-weight:600; color:${t.textPrimary};">Nenhuma divergência encontrada</div>
                <div style="font-size:12px; color:${t.textMuted}; margin-top:4px;">O imóvel foi devolvido nas mesmas condições.</div>
            </div>
        `;
    }

    // Agrupar por ambiente
    const ambientes = {};
    reportData.divergencias.forEach(div => {
        const ambiente = div.ambiente || 'Não especificado';
        if (!ambientes[ambiente]) ambientes[ambiente] = [];
        ambientes[ambiente].push(div);
    });

    let html = '';

    for (const ambiente in ambientes) {
        const items = ambientes[ambiente];
        const icon = getAmbienteIcon(ambiente);

        // Room header
        html += `
            <div style="margin-bottom:28px; page-break-inside:avoid;">
                <div style="display:flex; align-items:center; gap:10px; padding:14px 18px; background:${THEME === 'dark' ? '#252528' : '#1e2023'}; border-radius:12px 12px 0 0; color:#ffffff;">
                    <span style="font-size:16px;">${icon}</span>
                    <span style="font-size:14px; font-weight:700;">${ambiente}</span>
                    <span style="margin-left:auto; font-size:11px; background:rgba(255,255,255,0.1); padding:4px 12px; border-radius:20px; font-weight:500;">${items.length} ${items.length === 1 ? 'item' : 'itens'}</span>
                </div>
        `;

        // Divergence cards
        items.forEach((div, idx) => {
            const classDetails = getClassificationDetails(div.classificacao);
            const gravDetails = getGravidadeDetails(div.gravidade);
            const isLast = idx === items.length - 1;

            html += `
                <div style="border:1px solid ${t.cardBorder}; border-top:none; padding:20px; background:${t.cardBg}; ${isLast ? 'border-radius:0 0 12px 12px;' : ''} page-break-inside:avoid;">
                    <!-- Header -->
                    <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:14px; flex-wrap:wrap; gap:8px;">
                        <span style="font-size:14px; font-weight:700; color:${t.textPrimary};">${div.item || '—'}</span>
                        <div style="display:flex; gap:6px; flex-wrap:wrap;">
                            <span style="padding:3px 10px; border-radius:6px; font-size:9px; font-weight:700; text-transform:uppercase; letter-spacing:0.03em; background:${classDetails.badgeBg}; color:${classDetails.badgeColor}; border:1px solid ${classDetails.badgeBorder};">
                                ${classDetails.icon} ${classDetails.text}
                            </span>
                            <span style="padding:3px 10px; border-radius:6px; font-size:9px; font-weight:700; text-transform:uppercase; letter-spacing:0.03em; background:${gravDetails.badgeBg}; color:${gravDetails.badgeColor}; border:1px solid ${gravDetails.badgeBorder};">
                                ${gravDetails.icon} ${gravDetails.text}
                            </span>
                        </div>
                    </div>

                    <!-- Comparison -->
                    <div style="display:grid; grid-template-columns:1fr auto 1fr; gap:10px; align-items:stretch; margin-bottom:14px;">
                        <div style="padding:12px 14px; border-radius:8px; font-size:11px; line-height:1.7; color:${t.textSecondary}; background:${t.entradaBg}; border:1px solid ${t.entradaBorder};">
                            <span style="font-size:9px; font-weight:700; text-transform:uppercase; letter-spacing:0.08em; color:${t.textMuted}; display:block; margin-bottom:6px;">ENTRADA</span>
                            ${div.estado_entrada || '—'}
                        </div>
                        <div style="display:flex; align-items:center; font-size:16px; color:${t.textMuted};">→</div>
                        <div style="padding:12px 14px; border-radius:8px; font-size:11px; line-height:1.7; color:${t.badgeDangerColor}; background:${t.saidaBg}; border:1px solid ${t.saidaBorder};">
                            <span style="font-size:9px; font-weight:700; text-transform:uppercase; letter-spacing:0.08em; color:${t.badgeDangerColor}; display:block; margin-bottom:6px;">SAÍDA</span>
                            ${div.estado_saida || '—'}
                        </div>
                    </div>

                    <!-- Description/Justification -->
                    ${div.descricao || div.justificativa ? `
                    <div style="font-size:11px; color:${t.textSecondary}; line-height:1.7; padding:10px 14px; background:${t.goldDim}; border-radius:8px; border-left:3px solid ${t.gold};">
                        ${div.descricao ? `<strong>Descrição:</strong> ${div.descricao}` : ''}
                        ${div.descricao && div.justificativa ? '<br>' : ''}
                        ${div.justificativa ? `<strong>Justificativa:</strong> ${div.justificativa}` : ''}
                    </div>` : ''}
                </div>
            `;
        });

        html += '</div>'; // fecha room-section
    }

    return html;
}

// ============================================================
// ITENS SEM ALTERAÇÃO
// ============================================================
function generateItensSemAlteracao() {
    if (!reportData.itens_sem_alteracao || reportData.itens_sem_alteracao.length === 0) return '';

    let html = `
        <div style="margin-bottom:28px;">
            ${sectionTitle('Itens Sem Alteração')}
            <div style="display:flex; flex-wrap:wrap; gap:8px;">
    `;

    reportData.itens_sem_alteracao.forEach(item => {
        html += `
            <span style="display:inline-flex; align-items:center; gap:6px; padding:6px 14px; background:${t.noChangeBg}; border:1px solid ${t.noChangeBorder}; border-radius:20px; font-size:11px; font-weight:500; color:${t.noChangeColor};">
                ✓ ${item}
            </span>
        `;
    });

    html += '</div></div>';
    return html;
}

// ============================================================
// RECOMENDAÇÕES
// ============================================================
function generateRecomendacoes() {
    if (!reportData.recomendacoes || reportData.recomendacoes.length === 0) return '';

    let html = `
        <div style="margin-bottom:28px;">
            ${sectionTitle('Recomendações')}
    `;

    reportData.recomendacoes.forEach((rec, index) => {
        html += `
            <div style="display:flex; gap:14px; padding:14px 0; border-bottom:1px solid ${t.dividerColor}; align-items:flex-start;">
                <div style="width:28px; height:28px; background:${THEME === 'dark' ? '#252528' : '#1e2023'}; color:${t.gold}; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:700; flex-shrink:0;">${index + 1}</div>
                <div style="font-size:12px; color:${t.textSecondary}; line-height:1.7; padding-top:5px;">${rec}</div>
            </div>
        `;
    });

    html += '</div>';
    return html;
}

// ============================================================
// SECTION TITLE HELPER
// ============================================================
function sectionTitle(title) {
    return `
        <div style="display:flex; align-items:center; gap:10px; margin-bottom:20px; padding-bottom:10px; border-bottom:2px solid ${t.cardBorder};">
            <div style="width:4px; height:20px; background:${t.gold}; border-radius:2px;"></div>
            <span style="font-size:16px; font-weight:700; color:${t.textPrimary}; letter-spacing:-0.02em;">${title}</span>
        </div>
    `;
}

// ============================================================
// MONTAR HTML FINAL
// ============================================================
const dataGeracao = new Date().toLocaleDateString('pt-BR');
const horaGeracao = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
const periodoLocacao = reportData.periodo_locacao_dias
    ? `${reportData.periodo_locacao_dias} dias (${Math.floor(reportData.periodo_locacao_dias / 30)} meses)`
    : 'Não informado';

const htmlContent = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Relatório Comparativo - ${reportData.codigo_imovel}</title>
