const items = $input.all();

for (const item of items) {
  // Guardar referência aos binários ANTES de modificar
  const originalBinary = item.binary || {};

  // Extrair dados JSON do body
  item.json = {
    codigo_imovel: item.json.body?.codigo_imovel || item.json.codigo_imovel || '',
    endereco: item.json.body?.endereco || item.json.endereco || '',
    proprietario: item.json.body?.proprietario || item.json.proprietario || '',
    inquilino: item.json.body?.inquilino || item.json.inquilino || ''
  };

  const binaryKeys = Object.keys(originalBinary);
  const newBinary = {};

  // ─── Estratégia 1: Já existem com os nomes corretos ───
  if (originalBinary.pdf_entrada) {
    newBinary.pdf_entrada = originalBinary.pdf_entrada;
  }
  if (originalBinary.pdf_saida) {
    newBinary.pdf_saida = originalBinary.pdf_saida;
  }

  // ─── Estratégia 2: Identificar por fileName ou nome da chave ───
  if (!newBinary.pdf_entrada || !newBinary.pdf_saida) {
    for (const key of binaryKeys) {
      if (newBinary.pdf_entrada && newBinary.pdf_saida) break;
      if (originalBinary[key] === newBinary.pdf_entrada || originalBinary[key] === newBinary.pdf_saida) continue;

      const fileName = (originalBinary[key].fileName || '').toLowerCase();
      const keyLower = key.toLowerCase();

      const isEntrada = fileName.includes('entrada') || keyLower.includes('entrada');
      const isSaida = fileName.includes('saida') || fileName.includes('saída') || keyLower.includes('saida') || keyLower.includes('saída');

      if (!newBinary.pdf_entrada && isEntrada) {
        newBinary.pdf_entrada = originalBinary[key];
      } else if (!newBinary.pdf_saida && isSaida) {
        newBinary.pdf_saida = originalBinary[key];
      }
    }
  }

  // ─── Estratégia 3: Atribuir por posição (1º = entrada, 2º = saída) ───
  if (!newBinary.pdf_entrada || !newBinary.pdf_saida) {
    const usedValues = [newBinary.pdf_entrada, newBinary.pdf_saida].filter(Boolean);
    const unusedKeys = binaryKeys.filter(k => !usedValues.includes(originalBinary[k]));

    if (!newBinary.pdf_entrada && unusedKeys.length > 0) {
      newBinary.pdf_entrada = originalBinary[unusedKeys[0]];
      unusedKeys.shift();
    }
    if (!newBinary.pdf_saida && unusedKeys.length > 0) {
      newBinary.pdf_saida = originalBinary[unusedKeys[0]];
    }
  }

  // ─── Debug: lançar erro claro se ainda faltam binários ───
  if (!newBinary.pdf_entrada || !newBinary.pdf_saida) {
    const keysInfo = binaryKeys.map(k => `${k}: "${originalBinary[k].fileName || 'sem nome'}"`).join(', ');
    throw new Error(
      `Binários não encontrados! ` +
      `pdf_entrada: ${!!newBinary.pdf_entrada}, pdf_saida: ${!!newBinary.pdf_saida}. ` +
      `Chaves recebidas: [${keysInfo || 'NENHUMA'}]. ` +
      `Verifique se o frontend envia os arquivos corretamente.`
    );
  }

  item.binary = newBinary;
}

return items;

