const item = $input.first().json;
const geminiResponseText = item.candidates[0].content.parts[0].text;

// Limpar possíveis marcações markdown
let jsonText = geminiResponseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let reportData;
try {
  reportData = JSON.parse(jsonText);
} catch (e) {
  // Tentar encontrar JSON dentro do texto
  const jsonMatch = geminiResponseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      reportData = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      throw new Error("Erro ao parsear JSON: " + e2.message + "\nTexto: " + jsonText.substring(0, 500));
    }
  } else {
    throw new Error("Nenhum JSON encontrado na resposta do Gemini");
  }
}

// Calcular totais se necessário
if (!reportData.total_divergencias && reportData.divergencias) {
  reportData.total_divergencias = reportData.divergencias.length;
}

if (!reportData.divergencias_por_tipo && reportData.divergencias) {
  reportData.divergencias_por_tipo = {
    desgaste_natural: 0, dano_inquilino: 0, melhoria: 0,
    item_ausente: 0, item_adicionado: 0, indefinido: 0
  };
  reportData.divergencias.forEach(div => {
    if (reportData.divergencias_por_tipo.hasOwnProperty(div.classificacao)) {
      reportData.divergencias_por_tipo[div.classificacao]++;
    } else {
      reportData.divergencias_por_tipo.indefinido++;
    }
  });
}

// Garantir que os dados do imóvel estejam presentes
